        public void AddDevice(BasicTriListWithSmartObject device)
        {
            Devices.Add(device);
            ComponentMediator.HookSmartObjectEvents(device.SmartObjects[ControlJoinId]);

            ((TelevicConferoDemo.Main.RequestingWidgetList.RequestingWidgetList)RequestingWidgetList).AddDevice(device);

            ((TelevicConferoDemo.Main.SpeakingWidgetList.SpeakingWidgetList)SpeakingWidgetList).AddDevice(device);

            ((TelevicConferoDemo.Main.SeatWidgetList.SeatWidgetList)SeatWidgetList).AddDevice(device);

            ((TelevicConferoDemo.Main.MeetingWidgetList.MeetingWidgetList)MeetingWidgetList).AddDevice(device);
        }

        public void RemoveDevice(BasicTriListWithSmartObject device)
        {
            Devices.Remove(device);
            ComponentMediator.UnHookSmartObjectEvents(device.SmartObjects[ControlJoinId]);

        ((TelevicConferoDemo.Main.RequestingWidgetList.RequestingWidgetList)RequestingWidgetList).RemoveDevice(device);

        ((TelevicConferoDemo.Main.SpeakingWidgetList.SpeakingWidgetList)SpeakingWidgetList).RemoveDevice(device);

        ((TelevicConferoDemo.Main.SeatWidgetList.SeatWidgetList)SeatWidgetList).RemoveDevice(device);

        ((TelevicConferoDemo.Main.MeetingWidgetList.MeetingWidgetList)MeetingWidgetList).RemoveDevice(device);
        }

